insert into public.resources (id, name, category, county, counties, communities, image_url, description, website, telephone, email, address, facebook, instagram, verified, age_rating, age_reason) values
  ('wS3PQcWURi-vUKg9n7rSyg', 'Adult Gay Male 18+ Friendship Circle', 'Support Circles', 'Salt Lake County', array['Salt Lake County','Utah County','Washington County']::text[], array['Gay Men']::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/Encircle_Logo.png', 'This friendship circle is for adults (18+) that identify as gay and male.

Friendship Circles? 

These groups are designed to provide a connection with folx you identify with and help you manage the trials you encounter every day. Friendship Circles create an opportunity for you to take control and thrive in your own life. Friendship Circles provide opportunities for sharing, connection, and support by discussing issues and experiences relevant to each group, often exploring the intersectionality of conservative cultures, spirituality, sexuality, social issues, transitional issues, and health issues and how it impacts us. The groups also provide a great support network—members in similar circumstances with similar feelings with whom they can share in an open and unedited fashion. 

Groups organized by sexuality, age, and/or gender identity.

For schedules and more information, please vis', null, null, null, null, null, null, false, null, null),
  ('Feys3ZGoRG-upYBwcDRwjg', 'Advanced Awareness Counseling', 'Mental Health/Counseling', 'Salt Lake County', array['Salt Lake County','Utah County']::text[], '{}'::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/61148a83af542c52d9760291_196587-1724580-3_320x400.jpg', 'We consist of a network of qualified mental health providers who have been selected for outstanding educational credentials, experience in the field, exceptional client care principles, high integrity, and expertise in particular areas of specialty.

Our various practitioners have proficiency in faith transitions, minority concerns, marriage counseling, couples counseling, family therapy, PTSD and trauma-related conditions (including EMDR therapy), generalized anxiety and social anxiety, gender dysphoria, gender and transgender specialized care, depression, suicide prevention, bipolar disorder, borderline personality disorder, adolescents and children, play therapy, sand tray therapy, anger management, grief and loss, and much more.

Our facility and our counselors are an ally to the LGBTQ+ community, and we provide support and affirming counseling for individuals of all orientations, id', 'advancedawarenesscounseling.com', '(385) 455-3768', null, null, null, null, true, null, null),
  ('IqikfxE6ScuYfDS1mzcgtw', 'Aromantic/Asexual Adult Friendship Circle', 'Support Circles', 'Salt Lake County', array['Salt Lake County','Utah County','Washington County']::text[], array['Asexual']::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/Encircle_Logo.png', 'This friendship circle is for adults (18+) who identify on the spectrum of Aromantic/Asexual. 

