  ('J3ZoWtatSG6B7sm0Qy0xiQ', 'Logan Pride', 'Pride Center', 'Cache County', array['Cache County']::text[], array['Age 18 and up.']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5633d794cb9119b3671eae_5f36a981be85343e64aea29d_Logan%2520Pride.png', 'Logan Pride strengthens, serves, and advocates for the Cache Valley LGBTQ community, including individuals, their families, and allies. We strive to bring our communities together in equality and love.', 'https://www.loganpride.org/', null, 'info@loganpride.org', '69 E 100 N, Logan, UT 84321', 'https://www.facebook.com/loganprideUT/', 'https://www.instagram.com/loganprideut/', true, null, null),
  ('lz.EUHppSQ6juJvyT-RAqQ', 'Love And Lift Inspirational Sunday', 'FHE/Sunday Service', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60f7a10284ee1c4841b27f47_81678267_10221067264009177_4643021326724890624_n.jpg', 'A place to be uplifted by others who walk the same road. This group represents those from different religions and faiths. Some are still in the LDS faith and some are completely out. We even have some who are agnostic but still want to feel uplifted and have a place to share their voice and feelings.

For more information and access please contact Jordan via Facebook below.', null, null, null, null, 'https://www.facebook.com/MusicFan7737', 'https://instagram.com/lgbtqsundayschool?utm_medium=copy_link', false, null, null),
  ('WukG5owtTUCU45NUOac7QQ', 'Mama Dragons', 'Support Organization', null, '{}'::text[], array['Parent']::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/file.png', 'About Us: Mama Dragons is a support organization for Mormon and former-Mormon mothers of LGBTQ children. Mama Dragons exist to inspire and empower mothers. We actively promote healthy, loving, and supportive environments for mothers of LGBTQIA children.Our Mission: We support, educate, and empower mothers of LGBTQ children.', 'http://Mamadragons.org', null, 'info@mamadragons.org', null, 'https://www.facebook.com/mamadragons/', 'https://www.instagram.com/themamadragons/?hl=en', true, null, null),
  ('2fUnN1.NSieg8xTa-oMDrw', 'Mama Dragons Facebook Group', 'Online Community', null, '{}'::text[], array['Parent']::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/file.png', 'This Mama Dragons Main Group on Facebook is the primary support group for all mothers of LGBTQ children navigating this sometimes challenging journey within their family and community. This group strives to be a space free of judgment between members and one that creates a safe place for conversation and support for individuals regardless of cultural or religious backgrounds. Mamas can ask questions, share success stories, share heartaches and heartbreaks, request and give advice, and bring a wealth of knowledge and experience to others in the group.

For more targeted needs and discussions, Mama Dragons also offers Facebook subgroups. Once you are a member of this main support group (or the Madres Dragones Facebook group), you can be invited – or request an invitation – to join other Mama Dragons subgroups listed below that meet your needs.', null, null, null, null, 'facebook.com/groups/953372108027028', null, false, null, null),
  ('a.YwfdysdTv6cEi9YtPsqYA', 'Men Finding Peace - Salt Lake City', 'Support Circles', 'Salt Lake County', array['Salt Lake County']::text[], array['Gay Men']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb49c263c18f396ea792537_mfpslc.jpg', 'What is Men Finding Peace?

More than a support group, more than a church meeting, Men Finding Peace is a group of men who share common goals and needs.  It is a place where men can be authentic and learn from other gay/SSA men from our everyday experiences, faith, and insight. To give strength to those who strive to live a covenant life of faith or those men who are just seeking peace and acceptance wherever they may be on their journey. It’s a place where ideas are shared to find strength, hope, and resolve with like men who share a common bond in brotherhood. A group that provides fellowship, purpose, and meaning through group sharing and other activities. 

The Men Finding Peace group meets every Wednesday at 7:00 pm until 8:30 pm. *Note current meetup information available on the Men Finding Peace Salt Lake City Facebook Group. 

*Disclaimer*: Men Finding Peace is an independent gro', 'menfindingpeace.blogspot.com', null, null, null, 'http://www.facebook.com/groups/1038606652939212/', null, false, null, null),
  ('2Y7BD9v-Q4yf6p5Yx8usjQ', 'Men Finding Peace - Utah Valley', 'Support Circles', 'Utah County', array['Utah County']::text[], array['Gay Men']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb49cabb50ea69dde81ea0c_mfpuv.jpg', 'More than a support group or a church meeting, “Men Finding Peace” is an independent group of men who share common goals, needs, and who want to participate in a gospel-oriented and positive association. It serves as a forum where men can learn from each other what it means to experience SSA and simultaneously live a covenant life of faith and hope within the bounds the Lord has set. It is a place to learn how others have found strength, resolve, and peace within themselves, their families, and other men who share a common bond in brotherhood.In this sense, Men Finding Peace accepts and adopts the mission of North Star International* to empower individuals and families, addressing sexual orientation or gender identity issues, to genuinely and joyfully live the Gospel of Jesus Christ, and to keep sacred covenants.We recognize that SSA is a complex subject often causing great inner conflic', 'mfpuv.wordpress.com', null, 'menfindingpeaceuv@gmail.com', null, null, null, true, null, null),
  ('S-6EPflFQKG2aei2KYi9fQ', 'Millennials Online Community', 'Online Community', null, '{}'::text[], '{}'::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png', 'This group is for individuals who were born 1980-2000. This group is meant to be a safe space that affirms each individual''s sexuality, faith or lack of faith. This is a space for compassionate support and fellowship of all LGBTQ and allied people with an LDS background. This space is also used to provide ideas and information about events, socials, and other programming that would be effective for LGBTQ Mormons, their families, friends, and church leaders. No matter the personal path you are on if you believe in Affirmation and it''s future, this is the right group for you.', null, null, null, null, 'https://www.facebook.com/groups/affirmationmillennials', null, false, null, null),
  ('2zCsEegaSsyRuWIscMN8DA', 'Mixed Orientation Families Online Community', 'Online Community', null, '{}'::text[], array['Mixed Orientation']::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png', 'An online community by Affirmation. For families impacted by Mixed Orientation Marriage (MOM). This group invites married MOM couples, as well as both gay, straight, and bisexual ex-spouses to join.To join please connect with Ron Raynes via Facebook below:', null, null, null, null, 'https://www.facebook.com/ron.raynes.1', null, false, null, null),
  ('PxX9ghZDRZ2Ij9IO4Skdtw', 'Mormon and Gay Subreddit', 'Online Community', null, '{}'::text[], array['LDS']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611490ab8fac2daf3bde33ec_communityIcon_ndkyxb5uwyb61.jpg', 'This is a subreddit where LGBTQ+ members of The Church of Jesus Christ of Latter Day Saints (or past members, or anyone else) can talk about their experiences being LGBTQ+. A place to promote discussions, have fun, ask questions, make friends, and find resources. You are not in this alone!', 'reddit.com/r/MormonandGay', null, null, null, null, null, false, null, null),
  ('PRCT24nnQoi3Rj8KukanLw', 'National Center for Transgender Equality ID, Docs, and Name Change Guide', 'Name/Gender Change Assistance', null, '{}'::text[], array['Trans']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611490d1d07df429168408d4_yo3Cw5wy_400x400.jpg', 'Welcome to our one-stop hub for name and gender change information. Find out how to update your name and gender on state and federal IDs and records.', 'https://transequality.org/documents/state/utah', '(202) 642-4542', null, null, 'https://www.facebook.com/transequalitynow', null, true, null, null),
