  ('oDtpVM00QsyFq5h1F.2ohQ', 'Now Playing Utah', 'Publications/Media', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114912ad07df458b9840aa0_NPU-logo-2020a.png', 'The mission of NowPlayingUtah is to increase awareness about arts and cultural opportunities in Utah by providing a comprehensive events resource. NowPlayingUtah has a database of LGBTQ+ positive arts and cultural opportunities in Utah.', 'https://t2m.io/now-playing-lgbtq', null, null, null, null, null, false, null, null),
