  ('POgh81.-QtO3Onj6sDP.zA', 'Ogden Pride', 'Pride Center', 'Weber County', array['Weber County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb54d2aaf5bae6788c74a9b_Ogden%20Pride.jpg', 'Our Mission: Ogden Pride celebrates and supports the LGBT community, individuals and their families and allies in Northern Utah in building and strengthening inclusive communities. We are committed to excellence in advocacy, educational programs and services.', 'ogdenpride.org', null, null, null, 'https://www.facebook.com/OgdenPrideInc/', null, false, null, null),
