  ('JGGBADz6TGqimUS4sXDwfQ', 'On the Record | A Chronology of LGBTQ+ Messaging', 'Publications/Media', null, '{}'::text[], array['LDS']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5631ab2220c976a31841d1_5f2c3bdfa932cb1decb0e7e3_cbbea37f.jpeg', 'On the Record, an interactive PDF document, is intended to establish a historical accounting of the official statements provided by The Church of Jesus Christ of Latter-day Saints through the Church’s education, policy, disclosure, and messaging regarding LGBTQ+ topics.', 'lattergaystories.org/record', null, null, null, null, null, false, null, null),
  ('OadsO.TxR4-HOZ4VrIKXeA', 'Online Parent Support Group', 'Online Community', null, '{}'::text[], array['Parent']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f2c881346237b6a67ee1976_I%27ll%20Walk%20With%20You.jpg', 'Welcome to the I''ll Walk With You Facebook group for LDS parents of LGBT children. This group is to provide support for LDS parents who want to stay active in the church while supporting their LGBT children or family members. We hope you find support for yourself and give support to others here.', null, null, null, null, 'https://www.facebook.com/groups/WalkWithYouLDSParentsOfLGBTQ/?fref=nf', null, false, null, null),
  ('UgIAWXyvTs2LuuX-3se1NQ', 'Parents and Caregivers Support Group', 'Support Circles', 'Salt Lake County', array['Salt Lake County']::text[], array['Parent']::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg', 'PCSG is a peer-led support group that meets weekly on Thursdays from 6:00-7:30. It is open to all parents and caregivers of LGBTQ+ youth.', 'https://www.utahpridecenter.org/youth-programs/y-parent-caregiver-sg', '801-539-8800', 'youth@utahpridecenter.org', '1380 South Main, SLC, UT, 84115', null, null, true, null, null),
  ('hwX0r3DCRx-YohwT-j6JDQ', 'Parents Support Group', 'Support Circles', 'Cache County', array['Cache County']::text[], array['Parent']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f358fc72b040487de0d14ba_Cache%20Pride.jpg', 'Our Parent group is open to all parents of and those in care of LGBTQIAP+ youth or are LGBTQIAP+ parents of youth. This group ordinarily meets as time permits. Parents work hard to take care of their children and this group will give parents an opportunity to socialize, give/receive information, advice, emotional, and moral support. Families have an opportunity to benefit from the unique connection that exists amongst families of children &amp; youth who are LGBTQIAP+ and may experience mental health challenges. Also, be on the lookout for family events and community nights.Located at 596 E 900 N, Logan, UT 84321', 'cachepridecenter.org', '(435) 363-5473', null, null, 'https://www.facebook.com/CachePrideCenter/', null, true, null, null),
  ('F19iMQpUQFGWVawPQES5vQ', 'Pathways Real Life Recovery', 'Mental Health/Counseling', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114914ff9a74f16afeb892c_Pathways.png', 'Pathways Real Life Recovery understands the numerous challenges that the LGBTQ+ community go through living in a heteronormative world, and it be even more challenging in the super-conservative state of Utah. Many gay people clash with loved ones due to their identity, and even years later the pain can linger. Sometimes, it’s a close friend or family cutting off all ties, or in other times, it’s bitter words and vitriol spewed in the heat of the moment that can''t be forgotten.

Regardless if you seek therapy for issues related to your LGBT status or not, it is imperative you feel supported and able to speak freely in order to benefit from the therapeutic experience. This is especially true for those confronted with the double stigma of mental health issues and LGBT orientation. Pathways is an LGBT counselor in Utah for teens and adults who are seeking professional counseling. We can help', 'https://pathwaysreallife.com/lgbtq-counselor-in-utah/', '801-895-3006', 'info@pathwaysreallife.com', '8706 S 700 E #205, Sandy, UT 84070', 'https://www.facebook.com/PathwaysRealLifeRecovery', 'https://www.instagram.com/pathwaysrealliferecovery/', true, null, null),
  ('OoBxKQKhRe6Eh5Gpo4Tgwg', 'Peculiar - Allies and Appetizers', 'Speaker Series', 'Salt Lake County', array['Salt Lake County']::text[], array['Parent']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60b4129762daab36ec2515f5_Peculiar.png', 'Mission Statement: To create safe spaces, filled with great conversation and a new understanding of how to better love and respect our LGBTQ+ family.', 'https://www.thepeculiar.org/allies-and-appetizers', '(801) 628-8509', null, null, 'https://www.facebook.com/thepeculiarorg', null, true, null, null),
  ('eEcoTbtXTbKRn.A9W.Eqqg', 'Peculiar Journal', 'Publications/Media', 'Utah County', array['Utah County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114919a500330dbad459bde_Peculiar%20Journal.PNG', 'Peculiar is a queer literary journal showcasing prose, poetry, art, and photography. With our roots in the Mormon stronghold of Provo, Utah, peculiar began as a way to recognize the creative talents of the often-overlooked queer community within Utah’s unique culture. As our journal has grown over the past few years—and our staff has begun setting roots nationwide—we’ve decided to broaden the scope of peculiar to include queer voices from anywhere and everywhere. No matter how far you are or how quietly you whisper, know that we hear you.
​
​In our first issue, co-editor-in-chief Aaron Gates wrote the following in his foreword: “To belong, isn''t that what we are fighting for, constantly? Every day a wave surges against us, telling us we are too different, telling us we have no place, telling us that something is wrong with us. No one can tell you what you are worth; that is for you to de', 'peculiarjournal.com', '801-891-9618', 'peculiarjournal@gmail.com', '145 E Center St #2A Provo, UT 84606', 'https://www.facebook.com/peculiarjournal/', 'https://instagram.com/peculiarjournal?igshid=yvlxg1m8eipq', true, null, null),
  ('BOV6Uv1hRNeGvOMhvOWJ7g', 'Peculiar Stories', 'Video Project', null, '{}'::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60b4129762daab36ec2515f5_Peculiar.png', 'Peculiar Stories is an opportunity to share your personal stories and/or insight on your experiences as a member of the LGBTQ+ community. Our community is strengthened as a whole when we share these stories. These stories are intended to bring awareness, change, and ultimately save the lives of our LGBTQ+ youth and community. We are grateful for the courage and the vulnerability shown here as well as the example given. Please honor these stories. They are sacred.', 'https://www.thepeculiar.org/peculiar-stories', null, null, null, null, null, false, null, null),
  ('B-NaH5McQcKW7bpKXmkvnQ', 'Planned Parenthood Association of Utah', 'Wellness/Medical', null, '{}'::text[], '{}'::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/5f36ad95b2ae3f30b8d8e28b_5f36abc5c9770f898e299192_Planned_20Parenthood.jpeg', 'Planned Parenthood Association of Utah shares the vision of an equitable world articulated by the Planned Parenthood Federation of America: where sexual and reproductive rights are basic human rights, where access to health care doesn''t depend on who you are and where you live, and where every person has the opportunity to choose their own path to a healthy and meaningful life. Our mission is to empower Utahns of all ages to make informed choices about their sexual health, to ensure access to affordable, quality health care and education, and protect their right to do so.', 'plannedparenthood.org/planned-parenthood-utah', null, null, null, null, null, false, null, null),
  ('H6i3fbAySKKf6qQ8gcEWFQ', 'Pre-Teen Support Group', 'Support Circles', 'Cache County', array['Cache County']::text[], array['Youth']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f358fc72b040487de0d14ba_Cache%20Pride.jpg', 'Our Preteen Group is open to all LGBTQ+ and LGBTQ+ affirming youth ages 10-14. We give our preteens a monitored platform to communicate with each other throughout the week and a fixed opportunity to reach out for mutual support from their peers. This allows our preteens to communicate and build a bond with each other, as well as CPC volunteers, for ongoing support and a sense of belonging outside of our Tuesday night group.', 'cachepridecenter.org', '435-363-5473', 'cachepridecenter@gmail.com', null, 'https://www.facebook.com/CachePrideCenter/', null, true, null, null),
  ('3hxLOeqvR7C1WCaD9-Wfsw', 'Prepare Online Community', 'Online Community', null, '{}'::text[], array['LDS']::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png', 'This group provides fellowship for LGBTQ people who desire to attend the LDS church and are supportive of everyone whether they''re in a same-sex relationship, an opposite-sex relationship, or celibate/abstinent.', null, null, null, null, 'https://www.facebook.com/groups/TheLordWillPrepare/', null, false, null, null),
  ('jJOvLyLgTGiosc3ALjCGww', 'Pride of Southern Utah', 'Pride Center', 'Washington County', array['Washington County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611491d80dac646a9ddf7c79_Southern%20utah.png', 'Together we can make a change.

Pride of Southern Utah is a grass roots grown non-profit group of who wants to see a change. A change of attitude, acceptance, perspective and love within and surrounding the LGBTQ+ community. Pride of Southern Utah has partnered with A.R.T.S. Inc. as our fiscal partner which gives us non-profit status. Every Dollar, every cent for that matter goes back into the festival and the LGBTQ+ community. While we might be small, we are big in heart, determination and might. Together we can make a change. But we need your help. Whether you are a vendor, volunteer, entertainer or a sponsor we hope that you will join us. Thank you for time and care. 

Who we are: Pride of Southern Utah is a non-profit organization founded on the belief that everyone belongs. Whether you are a member of the LGBTQ+ community or one of our Allies, we want to serve you.   

Philosophy: B', 'https://www.prideofsouthernutah.org/', null, null, '307 North Main Street, St. George, UT, 84770', 'https://www.facebook.com/DiscoverPride/', null, false, null, null),
  ('AChbgTB1R2yLdMSfPVLGWw', 'Progressive Paths Therapy', 'Mental Health/Counseling', 'Utah County', array['Utah County']::text[], array['Adults']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6176016f3d9c192bef6c6e3d_Untitled%20design%20(21).png', 'Welcome to Progressive Paths Therapy! Does it feel like you can’t control your anxiety no matter how hard you try?

Are you feeling hopeless, isolated and not your usual self?

Are you going through a faith crisis, shift, or transition?

Does it feel like your marriage/couple relationship is breaking down?

Are you seeking for a healthier, closer family relationship?

Are you struggling with problematic or out of control sexual behavior?

Have you tried to solve the problems in your life on your own and realized you need help from someone else?

If you answered yes to any of these questions, then you have made the right choice by being here.

And we know this is hard. You''ve likely been debating seeking help for months, if not years. But we are so glad you found us and have taken the courageous step of being here.', 'progressivepathstherapy.com', '801-704-5066', 'info@progressivepathstherapy.com', '1175 South 800 East, 2nd floor Orem UT 84097', null, null, true, null, null),
  ('gVxtobVtQRWufksvAEX13g', 'Project Rainbow', 'Community Projects', 'Salt Lake County', array['Salt Lake County','Davis County','Weber County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114921ddd8c32233dbb123a_101018466_969989456790318_6204034070993698816_n.png', 'Project Rainbow works to promote LGBTQ+ visibility throughout Utah and foster inclusivity in every corner of the state.

Flag Campaigns

Project Rainbow’s largest fundraiser is our flag campaigns. We stake flags in front of thousands of homes and businesses across Utah each year to celebrate the various pride festivals and events that take place throughout the State. 

Community Fund

The Project Rainbow Community Fund helps finance events or projects that align with our mission to “promote LGBTQ+ visibility throughout Utah.” Individuals, groups, and organizations can apply for grants ranging from $100-$7,000.

Transgender Day of Remembrance

For the week of Transgender Day of Remembrance (November 20) Project Rainbow stakes transgender pride flags along the Wasatch front from Ogden to Provo. Transgender Day of Remembrance (TDOR) is a day to increase visibility for the transgender commun', 'projectrainbowutah.org', '801-688-3275', 'lucas@projectrainbowutah.org', null, 'http://www.facebook.com/projectrainbowutah', 'http://instagram.com/projectrainbowutah', true, null, null),
  ('fJF9SttGTuehAGkbOhsjng', 'Provo Pride', 'Pride Center', 'Utah County', array['Utah County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fbd57ccc2d6fb05e3e7dbca_Provo%20Pride%20(1).jpg', 'We are the Provo Pride Council, a non-profit corporation organized to act as a community resource and symbol of hope and pride for residents of Utah County who may identify as gay, lesbian, bisexual, pansexual, transgender, transsexual, queer, questioning, intersex, intergender, asexual, etc. (abbreviated as LGBTQ or LGBT for simplicity).MISSIONOur mission is to support and celebrate the LGBTQ community in Provo and Utah County and foster understanding and ties with the larger community through a Pride Festival and other outreach programs. We affirm the equality, dignity, and right to self-determination of all people.VISIONWe aim to improve our support for the LGBTQ and ally community in Utah County by expanding our outreach programs, holding a Pride Parade in addition to the Festival, building an LGBTQ Center, providing help for the homeless youth population and preventing more homeless', 'provopride.org', null, null, null, 'https://www.facebook.com/ProvoPride/', 'https://www.instagram.com/provopride/?hl=en', false, null, null),
  ('Y6Goh0bBTF6vptUGvuGJMw', 'Q Pages', 'Publications/Media', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114924ffa744a5ce7773490_10500579_797248366972508_8796192887282199012_n.jpg', 'Welcome to the Q Pages, Utah’s businesses and services friendly to the gay, lesbian, bisexual, transgender and ally community. These companies have specifically chosen to market their availability to the LGBT community and have signed a pledge that they and their employees will treat us with dignity, respect, and fairness.', 'https://www.qpages.com/', '801-997-9763', null, '222 S Main St, Ste 500 Salt Lake City UT 84101', 'https://www.facebook.com/QPagesUtah', null, true, null, null),
  ('a-KtaHaNqQyKXUJ-MdtBq.Q', 'QTalks', 'Speaker Series', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb96adfcdd292cdcc7806c5_Equality%20utah.png', 'QTalks is a quarterly queer lecture series provided by the Equality Utah Foundation. Past guest speakers have included Dustin Lance Black, Samantha Allen, and more.', 'equalityutah.org/qtalks', null, null, null, null, null, false, null, null),
  ('bcyBXVGES-STi-sUdfqiBw', 'QUAC - Queer Utah Aquatics Club', 'Social Groups', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5634b6bf3eb9120c24b690_5f36b0880c5d7cd59e54b4ac_Quac.png', 'Queer Utah Aquatic Club, Inc. ( QUAC) is a 501(c)(3) non-profit organization dedicated to the promotion of adult, amateur swimming regardless of age, ability, gender identity, or sexual orientation. QUAC is the largest LGBTS sports club in Utah. QUAC offers swimmers and water polo players of all abilities a supportive and safe environment to improve their skills, get some exercise, meet people with similar interests and, if they so choose, the opportunity to compete. Whether you are interested in swimming, multi-sports, or water polo; whether you’re a former competitor or can barely doggy paddle, QUAC has something to offer. Come join us at practice and get involved with one of the biggest and friendliest sports groups in Utah! QUAC is also a Learn to Swim Program in cooperation and with grants from USMS ​Swimming Saves Lives Foundation.', 'https://www.quacquac.org/', null, 'info@quacquac.org', 'Fairmont Aquatic Center, 1044 East Sugarmont Drive, Salt Lake City, UT 84106', 'https://www.facebook.com/quacquac', 'https://www.instagram.com/quac_aquatics/', true, null, null),
  ('6KBmHqUSRYWJFPYdWstM-g', 'Queer Community Allies', 'Education/Advocacy', 'Utah County', array['Utah County']::text[], array['Youth']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114926aa2c30956464cf12f_QCA.jpg', 'Local GSA Support
We support GSAs (gay straight alliances/gender sexuality alliances; student-led with a teacher-staff-counselor advisor) in local high schools. Posters, stickers, flags, buttons, masks, wrapped snacks, books, funds for supplies, crafting items, board games, cards, guest visits from affirming adults, contacts from local businesses who can partner for donations… If they don''t have the resources for success, we try to help.

Classroom Decor & Educator Supplies
Teachers often ask us for buttons to distribute to faculty-friends and students and for posters, stickers and flags for their classrooms. If you’re a teacher who would like some items, reach out! We’d be happy to gift you some!

Community Events
We love going to Pride, joining other organizations at various city community nights, being involved with other local youth efforts, and hosting events to talk with educators ', 'queercommunityallies.org', null, 'contact@queercommunityallies.org', null, 'https://www.facebook.com/QueerCommunityAllies/', 'https://www.instagram.com/queercommunityallies/', true, null, null),
  ('Z8LBm637S.SleHlW3kZxCg', 'Queer Friends', 'Social Groups', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5634b4418da6b96c057ca7_5f36b0f42f3ef9bbbfebab19_Queer%2520Friends.png', 'Queer Friends: queer is normal. We are an all-inclusive social group of LGBTQIA+ friends having a great time in Salt Lake! This group is open to any gender-identity, sexual orientation, monogamous and non-monogamous relationships AND queer-friendly allies. Singles, couples, friends and family are all welcome as long as they are queer-friendly. Our goal is to also create a safe, welcoming and supportive community. We especially welcome people who are questioning their identity and just starting the "coming out" process.<h2>Mission</h2><p>To create a safe, welcoming, and supportive all-inclusive community through normal social activities and education.</p><h2>Vision</h2>We envision a community of queer people and allies working together to create a culture of love, acceptance and nondiscrimination so all queer people can be true to themselves.We host a broad range of events using the Meetu', 'queerfriends.org', null, null, null, null, null, false, null, null),
  ('5hhHWAjISdSUNBwBqvMwvg', 'Queer Meals', 'Community Projects', 'Utah County', array['Utah County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f563d75e654801c2fec8991_5f36b04e5ad1bd42dc635fbb_cropped-QueerMeals_doodles_web-02%2520(1).png', 'Providing meals, groceries, love, and the occasional pizza. Life in Provo can be overwhelming for the LGBTQ community. Because of this, there are many groups in Provo that serve the LGBTQ community. QueerMeals is simply one more. We are open 24/7 to folks who need a safe space to sit, visit and decompress—where their pronouns will be respected and their individual paths will be cherished. We have extensive experience with suicide prevention counseling and visitors can expect to feel validated and appreciated. If you need to come over, or even if you do not want to leave your home but you would like a visit or a meal, send us a message and we’ll tell you how to find us.', 'http://QueerMeals.com', null, null, null, null, null, false, null, null),
  ('TzoFxQ7nRISXtvF5MhuZPw', 'Queer Mormon Therapists', 'Other', null, '{}'::text[], '{}'::text[], 'https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/NSfaaNV0fRhAK9yZqEUi/pub/6NVq18WZh85gz6ou74eX.png', null, null, null, null, null, null, null, false, null, null),
  ('V.RXFCIcSVmfTlxhWXPJCw', 'Queer Spectra', 'Publications/Media', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/NSfaaNV0fRhAK9yZqEUi/pub/3My94t7vhOSkQlhcLa9z.jpg', 'A safe space for artists who self-identify as LGBTQIA+ to showcase their works and engage audiences in conversation regarding art and queer identity.

Our Mission

Queer Spectra Arts Festival is dedicated to showcasing arts from multiple LGBTQIA+ perspectives. 
As curators, we aim to present a diverse array of voices, backgrounds, experiences, cultures, mediums, and artistic disciplines in order to celebrate queer artistic expressions. Queer Spectra Arts Festival challenges and contributes to contemporary understanding of queer discourse while promoting nuanced conversations between artists and audiences about queer identity and art.', 'https://www.queerspectra.com/', null, 'queerspectra@gmail.com', null, 'https://www.facebook.com/Queer-Spectra-Arts-Festival-422526101851501/?modal=admin_todo_tour', 'http://instagram.com/queerspectra', true, null, null),
  ('UsNLPOJNQG-I8nWHP12L3Q', 'Radical Adventure Riders SLC Chapter', 'Social Groups', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61731f738b5a81f47a7b8f87_151191169_636978377083881_6564652702243824200_n.jpg', 'RAR creates networks and programs to support femme, transgender, woman, and non-binary (FTWN-B) and Black, Indigenous, People of Color (BIPOC) in the cycling and outdoors scene.', 'https://radicaladventureriders.com/chapters/salt-lake', null, 'rar.saltlake@gmail.com', null, 'https://www.facebook.com/radical.adventure.riders', 'https://instagram.com/rar.saltlake', true, null, null),
  ('rOpcLkapTpWh61bC45v0FQ', 'RaYnbow Collective', 'College Resources', 'Utah County', array['Utah County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61d91f2f0d3d6d3eda28f567_Untitled%20design%20(44).png', 'The RaYnbow Collective is a volunteer organization located in Provo, Utah, focused on creating and identifying safe spaces for LGBTQ+ students, faculty, and staff at Brigham Young University. To accomplish this, we develop networks across Utah with organizations, businesses, artists, and activists to support BYU students wherever they are physically, emotionally, and spiritually.', 'linktr.ee/raynbow.collective', null, 'raynbow.collective@gmail.com', null, null, 'instagram.com/raynbow.collective', true, null, null),
  ('fxvTgp2YQ8-.mD.Fyc0uZQ', 'Rebirth OB/GYN', 'Wellness/Medical', 'Salt Lake County', array['Salt Lake County']::text[], array['Trans']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611b35386e7390ec22a2ec1a_Rebirth.jpg', 'Rebirth OBGYN is a Gender Center & OBGYN Clinic located in Salt Lake City, UT

Due to stigma and lack of knowledge, transgender individuals may not get the quality health care they need or deserve. Rixt Luikenaar, MD, FACOG, at Rebirth OB/GYN in Salt Lake City specializes in transgender health and manages both primary care and the specialized medical needs for transgender and gender-nonconforming individuals. To schedule an appointment, call the office today or book online.', 'rebirthobgyn.com', '801-272-3909', null, '2180 E. 4500 S., Suite 270, Salt Lake City, UT 84117', null, null, true, null, null),
  ('HZ-GSWvnSI2bBiMQUn-B.Q', 'Safe Space UT', 'Community Projects', 'Utah County', array['Utah County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/617337be6c595b0182d069f3_comingoutday_LOGO_11-final.png', 'Savannah Skyler and Jerilyn Hassell Pool teamed up to create a graphic to allow teachers a way to signal a commitment to learning and understanding of issues faced by sexual, gender, or racial minorities and a willingness to create and maintain safe space to help those who struggle. Based on “Ring Theory” by Dr. Susan Silk

• Promotes helpful and healthy patterns of support for the most vulnerable: “comfort in; dump out”

• Illustrates encompassing support for Black and Indigenous People of Color (BIPOC) and trans communities

• Emphasizes importance of the larger LGBTQ+ community as a resource while recognizing their need for safety, too

Support them in their goal to deliver posters and resource packets to Utah schools. Visit thier website!', 'safespaceut.com', null, null, null, 'https://www.facebook.com/SafeSpaceUT', null, false, null, null),
  ('VK8rnjZwR229YaoVVcQuUQ', 'Salt Lake City Gay Men''s Book Club', 'Social Groups', 'Salt Lake County', array['Salt Lake County']::text[], array['Gay Men']::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg', 'This book club is primarily for gay men but anyone is welcome to attend! We meet on the third Wednesday of each month (excluding holiday weeks). We meet at the Utah Pride Center on Main Street at 6:00. Bring a friend and feel free to check out the group even if you haven''t read the book! We vote on book selections about 1-3 months in advance.', null, null, null, '1380 S Main St, Salt Lake City, UT 84115', 'https://www.facebook.com/groups/276230999378620/', null, false, null, null),
  ('YfhvfKINQNiuRVjNzEX28Q', 'Salt Lake City Good Time Bowling League', 'Social Groups', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5634b3c4a75f588d5f853a_5f36b2d74ec0aace07dac1d0_Untitled%2520design.png', 'Utah''s Sunday night LGBTQS bowling league. We were founded in 1990. We are a handicap league (meaning all bowlers are welcome) that likes to have fun while we bowl. And not only do you get to bowl in a fun, relaxed, and welcoming atmosphere you are also raising money for charities. For more information and to join, join us on Facebook.', null, null, null, null, 'https://www.facebook.com/groups/saltlakegoodtimebowlingleague', null, false, null, null),
