  ('Hc8eW5DZTFCdx.0CuaXCNA', 'Utah Pride Center', 'Pride Center', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg', 'Mission: Utah Pride unites, empowers and celebrates Utah’s diverse LGBTQ+ community by providing a safe and welcoming space for education, partnership, service, and events which advance our collective health, wellness and success.', 'utahpridecenter.org', '+1 801 539 8800', 'information@utahpridecenter.org', '1380 South Main, SLC, UT, 84115', 'https://www.facebook.com/UTpridecenter/', 'https://www.instagram.com/utahpridecenter/?hl=en', true, null, null),
  ('aXDW.ri2T1WVHZ7CN0nfdg', 'Utah Pride Center Counseling', 'Mental Health/Counseling', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg', 'The Utah Pride Center’s Community Counseling practices an affirmative approach to psychotherapy, working with our young and older folks to uncover their interpersonal concerns within the context of their gender identity or sexual orientation.Our affirmative and supportive approach involves a strong focus on the therapeutic alliance, with therapists serving as advocates for the client and being mindful of the LGBTQ+ experience. Using this developmental, evidence-based and culturally sensitive understanding, our therapists engage in a meaningful and queer supportive approach.', 'http://utahpridecenter.org/mental-health', '801-539-8800', 'therapy@utahpridecenter.org', '1380 South Main, SLC, UT, 84115', null, null, true, null, null),
  ('a.WrxHMsgSaiwVqirzNH5XA', 'Utah Rainbow Hikers', 'Social Groups', 'Salt Lake County', array['Salt Lake County','Cache County','Davis County','Weber County']::text[], '{}'::text[], 'https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/NSfaaNV0fRhAK9yZqEUi/pub/egf4RgUsaw6OGJcfM1eq.jpg', 'A queer, trans, LGBTQ+ inclusive hiking group in Northern Utah. Join us as we create an inclusive outdoor community for us by us!', null, null, null, null, 'https://www.facebook.com/utahrainbowhikers', 'https://www.instagram.com/utahrainbowhikers/', false, null, null),
  ('uuVrXGNaRHizMkMEhS0Nyg', 'Utah SAGE', 'Support Circles', 'Salt Lake County', array['Salt Lake County']::text[], array['Senior']::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg', 'SAGE provides services and resources for the LGBTQ senior community.  SAGE has four foundational pillars and five areas of focus that support those foundational pillars.  Every program, group or event is designed with that support in mind.  SAGE supports each person so they can live their best senior lives.

FOUNDATIONAL PILLARS
- Community Education
- Provider Education
- Social Needs
- Advocacy


AREAS OF FOCUS SUPPORTING THE PILLARS

- Socialization (events, activities, functions, gatherings, outings, travel, networking)Emotional (relationships, love, caregiving, caretaking)
- Physical (housing, healthcare, transportation, financial, sexual health/well being, exercise)- 
- Spiritual (connectivity, self-awareness, renewal, self-enlightenment, re-invention and evolving)


You may reach Deb Hall - Director of Ault Programs below. Telephone extension x1017', 'https://www.utahpridecenter.org/senior-programs', '801 539 8800', 'debhall@utahpridecenter.org', null, null, null, true, null, null),
