  ('0H4DhOt6TNegCYDORtIIlg', 'VentureOUT Utah', 'Social Groups', null, '{}'::text[], '{}'::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f2cdc847f3202dc59be00e6_5f2c4f1cfb9fc058dd273767_103776206_10217058209786670_8504971671522307530_o.jpeg', 'LGBT friendly group, welcome to all. It is our goal to promote adult, amateur outdoor recreation regardless of age, ability, gender identity, or sexual orientation. We want to inspire a sense of community and comradeship between members and participants. Group members are encouraged to share their upcoming outdoor activities so that others may join in the fun.We love the outdoors and chances are, you do too! Getting OUTside is fun! We are what we want to be, but primarily focused as an outdoor camping and hiking group. Going outdoors or hosting a social event? We like those who will make just about any excuse to get together for a good time and outdoor recreation. See you on the trail!', null, null, null, null, 'https://www.facebook.com/groups/Venture.OUT.Utah', null, false, null, null),
  ('cZkVT0U9QC-KPmgHTSn.-w', 'Voices of Hope', 'Video Project', null, '{}'::text[], array['LDS']::text[], 'https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb495d33c18f3515b791d62_north%20star.jpg', 'The personal stories shared on this site serve as an extension of the book, the Voices of Hope. It is a living repository of faithful members of The Church of Jesus Christ of Latter-day Saints sharing their stories of how they seek to reconcile their sexual orientation or gender identity with their faith. you''ll hear how they have chosen to embrace the restored gospel, the inherent challenges they face, and how they’ve found peace in their decisions.', 'northstarlds.org/voices-of-hope', null, null, null, null, null, false, null, null),
