  ('O8QG0YCwQw2tZbYeNeiusQ', 'Youth Support Group', 'Support Circles', 'Salt Lake County', array['Salt Lake County']::text[], array['Youth']::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg', 'YSG is a peer-led support group that meets weekly on Tuesdays. There are two sessions; the 14-20 age group meets from 6:30 p.m. to 8:00 p.m. and the 10-14 age group meets from 6:00 p.m. – 7:30 p.m. An orientation is required.', 'utahpridecenter.org/youth-programs', null, null, null, null, null, false, null, null),
  ('kYrVp6sVSOWenGIZvZjSpA', 'Queerful Counseling', 'Mental Health/Counseling', 'Salt Lake County', array['Salt Lake County']::text[], '{}'::text[], 'https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/NSfaaNV0fRhAK9yZqEUi/pub/3OhaAly5tykKWqIzt9D0.jpg', '#### Mental health therapy specializing in queerness, sex therapy, and Mormon faith transitions.

Queerness, faith transitions, religious trauma, and sex. I can (and do) talk about these topics all day. Any one of these issues can seem overwhelming and impossible to deal with. As a therapist who has dealt with these issues myself, I bring both professional and personal experience to help you move forward. I know every person''s story and life is unique and I won''t project my experiences on you. However, you won''t have to explain the "Mormon lingo" or worry that I won''t understand the unique issues queer individuals face in a heteronormative and cisgender world.

When we meet, I want to make sure I understand you holistically and that you feel heard. I then work collaboratively with you to create a personalized plan moving forward. I can draw from a wide variety of modalities and technique', 'psychologytoday.com/us/therapists/colette-dalton-sandy-ut/860415', null, null, '9571 South 700 East STE #101, Sandy, UT 84070', null, 'https://www.instagram.com/queerfulcounseling', false, null, null),
  ('xl28gJgnQtqfc67WagG.dg', 'STARS in Action', 'Social Groups', 'Weber County', array['Weber County']::text[], array['Trans']::text[], 'https://hosting.photobucket.com/images/i/lgbtqut/OP_STARSBackground.jpg', 'Synergetic Trans Activists, Resources & Support

STARS in Action provides dedicated support for the transgender and gender non-conforming community.

**Our aims:**
- build community in Ogden through social meetings and events
- grow our social footprint in our communities through volunteering opportunities
- provide professional development through workshops and career resources
- offer resources and support to meet our community’s most pressing needs
- magnify our presence and programming through partnerships with community organizations.', 'https://www.ogdenpride.org/ogden-pride-center/stars-in-action/', null, 'info@ogdenpride.org', null, 'https://www.facebook.com/groups/starsinaction/', null, true, null, null),
  ('TTnviwJ0Sc6NGDj3sXedYg', 'Neurobehavioral Center for Growth', 'Mental Health/Counseling', 'Davis County', array['Davis County','Weber County','Salt Lake County']::text[], '{}'::text[], 'https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/GLyS34gJTOtHtpGe05Cl/pub/kdwS7CjotvJmt8ItsGgF.png', '## Let’s grow together.

Treatment paths unique to every child, teen, adult, and family.  We believe in celebrating you.

At NBCG, we offer personalized psychological, developmental, behavioral, and mental health services designed to empower individuals living with an array of complexities.

## We specialize in…', 'www.neurobcg.com', '801-683-1062', null, null, 'https://www.facebook.com/neurobcg', 'https://www.instagram.com/neurobcg/', true, null, null)
