insert into public.crisis_lines (name, description, action_label, telephone, position) values
  ('988 Suicide & Crisis Lifeline', 'Call or text 988. Free, confidential, 24/7 — for anyone in Utah.', 'Call 988', '988', 0),
  ('The Trevor Project', 'Crisis counseling for LGBTQ+ young people under 25.', 'Call 1-866-488-7386', '18664887386', 1),
  ('Trans Lifeline', 'Peer support run by and for trans people. No non-consensual active rescue.', 'Call 877-565-8860', '18775658860', 2),
  ('Utah Warm Line', 'Non-crisis peer support when you need to talk it through.', 'Call 1-833-773-2588', '18337732588', 3)
on conflict (name) do update set description = excluded.description, action_label = excluded.action_label, telephone = excluded.telephone, position = excluded.position;

delete from public.crisis_lines where name not in ('988 Suicide & Crisis Lifeline', 'The Trevor Project', 'Trans Lifeline', 'Utah Warm Line');

